// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != newOwner);
        vm.assume(caller != c.owner());
        address prevOwner = c.owner();
        vm.prank(caller);
        try c.setOwner(newOwner) returns (bool success) {
            bool ownerUnchanged = (c.owner() == prevOwner);
            if (caller != prevOwner) {
                assertTrue(ownerUnchanged, "non-owner should not change owner");
            }
        } catch {
            assertTrue(c.owner() == prevOwner, "owner changed on revert");
        }
    }
}
